$$
\begin{cases}\varepsilon_x=\dfrac{\sigma_x}E-\mu\dfrac{\sigma_y}E,\\\varepsilon_y=\dfrac{\sigma_y}E-\mu\dfrac{\sigma_x}E\end{cases}\quad\Rightarrow\quad\begin{cases}\sigma_x=\dfrac{E(\varepsilon_x+\mu\varepsilon_y)}{1-\mu^2},\\\sigma_y=\dfrac{E(\varepsilon_y+\mu\varepsilon_x)}{1-\mu^2}.\end{cases}
$$

$$
\begin{cases}m\ddot x_{\mathrm{equivalent}}=-\sigma_x\dfrac VL,\\m\ddot y_{\mathrm{equivalent}}=-\sigma_y\dfrac Vl\end{cases}\quad\Rightarrow\quad\begin{cases}\dfrac{mL\ddot\varepsilon_x}{12}+\dfrac{E(\varepsilon_x+\mu\varepsilon_y)}{1-\mu^2}\dfrac VL=0,\\\dfrac{ml\ddot\varepsilon_y}{12}+\dfrac{E(\varepsilon_y+\mu\varepsilon_x)}{1-\mu^2}\dfrac Vl=0.\end{cases}
$$
